      ],
      "rationale": "Authentication flows must be tested to confirm that multi-factor or two-factor authentication is enforced at AAL2."
    },
    {
      "requirement_id": "KDH-003",
      "methods": [
        "Test"
      ],
      "rationale": "Session timeouts and reauthentication triggers must be observed by running the system with defined inactivity and overall timeout values."
    },
    {
      "requirement_id": "KDH-004",
      "methods": [
        "Test"
      ],
      "rationale": "Account recovery scenarios must be executed to verify that notifications are sent to the representative or designee."
    },
    {
      "requirement_id": "KDH-005",
      "methods": [
        "Test"
      ],
      "rationale": "Notification dispatch must be tested to ensure all registered non-postal addresses receive account notifications."
    },
    {
      "requirement_id": "KDH-006",
      "methods": [
        "Test"
      ],
      "rationale": "The system must be run to verify that the citizen's session persists beyond the e-Devlet assertion validity window."
    },
    {
      "requirement_id": "KDH-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The federation transaction request structure must be inspected to confirm the presence of the VBP identifier and cryptographic nonce."
    },
    {
      "requirement_id": "KDH-008",
      "methods": [
        "Test"
      ],
      "rationale": "Assertions with incorrect audience identifiers must be submitted to verify that the system rejects them to prevent replay attacks."
    },
    {
      "requirement_id": "KDH-009",
      "methods": [
        "Test"
      ],
      "rationale": "Changing the telephone number must be tested to ensure it triggers the new authenticator binding process."
    },
    {
      "requirement_id": "KDH-010",
      "methods": [
        "Test"
      ],
      "rationale": "The system must be tested to verify that multiple authenticators can be successfully bound to a single account."
    },
    {
      "requirement_id": "KDH-011",
      "methods": [
        "Test"
      ],
      "rationale": "Binding a new authenticator must be tested to verify that the required authentication level is enforced based on the lower of the two AALs."
    },
    {
      "requirement_id": "KDH-012",
      "methods": [
        "Test"
      ],
      "rationale": "Adding an authenticator must be tested to confirm that an independent notification mechanism is triggered."
    },
    {
      "requirement_id": "KDH-013",
      "methods": [
        "Test"
      ],
      "rationale": "The confirmation code must be used successfully and then resubmitted to verify that the second attempt is rejected."
    },
    {
      "requirement_id": "KDH-014",
      "methods": [
        "Test"
      ],
      "rationale": "Assertions with invalid signatures must be submitted to verify that the system rejects them using the expected IdP verification key."
    },
    {
      "requirement_id": "KDH-015",
      "methods": [
        "Test"
      ],
      "rationale": "The same assertion must be submitted twice to verify that the second submission is rejected due to replay protection."
    },
    {
      "requirement_id": "KDH-016",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The federation initiation logic must be reviewed to confirm that VBP always acts as the RP in transactions."
    },
    {
      "requirement_id": "KDH-017",
      "methods": [
        "Test"
      ],
      "rationale": "Unsuccessful proofing attempts must be tested to ensure that error messages do not reveal whether specific attributes matched authoritative sources."
    },
    {
      "requirement_id": "KDH-018",
      "methods": [
        "Test"
      ],
      "rationale": "IAL2 proofing flows must be executed to verify that core attributes are validated against authoritative sources or via digital signatures."
    },
    {
      "requirement_id": "KDH-019",
      "methods": [
        "Test"
      ],
      "rationale": "Successful IAL2 proofing must be completed to verify that a notification is sent to the validated address."
    },
    {
      "requirement_id": "KDH-020",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The identity verification configuration and code must be reviewed to confirm that knowledge-based verification is not implemented or enabled."
    },
    {
      "requirement_id": "KDH-021",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The authentication configuration must be reviewed to ensure that email is not configured as an out-of-band authentication factor."
    },
    {
      "requirement_id": "KDH-022",
      "methods": [
        "Test"
      ],
      "rationale": "SMS codes must be submitted at various time intervals relative to sending to verify that only codes within the 5-minute window are accepted."
    },
    {
      "requirement_id": "KDH-023",
      "methods": [
        "Test"
      ],
      "rationale": "A valid SMS code must be submitted twice to verify that the second submission is rejected."
    },
    {
      "requirement_id": "KDH-024",
      "methods": [
        "Test"
      ],
      "rationale": "Failed authentication attempts must be made, followed by generating a new SMS code, to verify that the failed count is not reset."
    },
    {
      "requirement_id": "KDH-025",
      "methods": [
        "Test"
      ],
      "rationale": "Passwords with various compositions (e.g., all lowercase, no special characters) must be tested to verify that only length and blocklist checks are enforced."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KDH-051",
      "methods": [
