    },
    {
      "requirement_id": "KDH-069",
      "methods": [
        "Test"
      ],
      "rationale": "Keyboard operability is verified by navigating and interacting with all portal functions using only the keyboard without time limits."
    },
    {
      "requirement_id": "KDH-070",
