      "requirement_id": "KDH-072",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Link purpose clarity is verified by inspecting the link text and associated ARIA labels to ensure the purpose is clear from context."
    },
    {
      "requirement_id": "KDH-073",
      "methods": [
        "Test"
      ],
