    },
    {
      "requirement_id": "KDH-108",
      "methods": [
        "Test",
        "İnceleme"
      ],
      "rationale": "İletişim güvenliği (TLS vb.) yapılandırması inceleme ile, veri akışının şifrelenmesi ve bütünlüğü ise ağ trafiği analizi ile test edilmelidir."
    },
    {
      "requirement_id": "KDH-109",
      "methods": [
        "Test"
      ],
