{
  "decisions": [
    {
      "requirement_id": "KDH-026",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement specifies a functional behavior (rejecting short passwords, accepting long ones) that can be verified by executing the system with specific input lengths."
    },
    {
      "requirement_id": "KDH-027",
      "methods": [
        "Test"
      ],
      "rationale": "The character counting logic for Unicode code points can be verified by providing passwords with specific Unicode characters and observing the system's acceptance or rejection based on length."
    },
    {
      "requirement_id": "KDH-028",
      "methods": [
        "Test"
      ],
      "rationale": "The accessibility of password hints to unauthenticated users can be verified by attempting to access the hint endpoint or UI without authentication."
    },
    {
      "requirement_id": "KDH-029",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The absence of specific UI prompts (security questions) is best verified by inspecting the user interface design and code to ensure no such elements exist."
    },
    {
      "requirement_id": "KDH-030",
      "methods": [
        "Test"
      ],
      "rationale": "The system's handling of full password submission and verification without truncation can be tested by submitting passwords of varying lengths and checking the verification logic."
    },
    {
      "requirement_id": "KDH-031",
      "methods": [
        "Test"
      ],
      "rationale": "The blocklist comparison functionality can be verified by attempting to set passwords that are known to be on the blocklist and observing the rejection."
    },
    {
      "requirement_id": "KDH-032",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to compare the entire password rather than substrings can be tested by using passwords that contain blocklisted words as substrings but are not themselves on the blocklist."
    },
    {
      "requirement_id": "KDH-033",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection of blocklisted passwords and the provision of a reason can be verified by submitting a blocklisted password and checking the error message and system state."
    },
    {
      "requirement_id": "KDH-034",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The presence of guidance on choosing strong passwords, especially after rejection, is a UI feature that can be demonstrated by navigating to the relevant screens."
    },
    {
      "requirement_id": "KDH-035",
      "methods": [
        "Test"
      ],
      "rationale": "The compatibility with password managers and autofill can be verified by using a password manager to fill in the fields and checking if the system accepts the input."
    },
    {
      "requirement_id": "KDH-036",
      "methods": [
        "Test"
      ],
      "rationale": "The account recovery mechanisms can be verified by simulating recovery scenarios with different combinations of recovery codes and authenticators."
    },
    {
      "requirement_id": "KDH-037",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of an authenticator after 50 consecutive failed attempts can be verified by performing 50 failed logins and then attempting a successful login."
    },
    {
      "requirement_id": "KDH-038",
      "methods": [
        "Test"
      ],
      "rationale": "The disabling of multiple authenticators involved in failed attempts can be verified by simulating failures across multiple factors and checking their status."
    },
    {
      "requirement_id": "KDH-039",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement to re-bind a disabled authenticator before use can be verified by disabling an authenticator, attempting to use it, and then re-binding it."
    },
    {
      "requirement_id": "KDH-040",
      "methods": [
        "Test"
      ],
      "rationale": "The handling of e-Devlet responses that do not meet security levels can be verified by simulating such responses and observing the system's reaction."
    },
    {
      "requirement_id": "KDH-041",
      "methods": [
        "Test"
      ],
      "rationale": "The session AAL handling can be verified by creating a session at a specific AAL and checking if the system treats it at a higher AAL."
    },
    {
      "requirement_id": "KDH-042",
      "methods": [
        "Test"
      ],
      "rationale": "The prevention of fallback to insecure transport can be verified by attempting to downgrade the connection from HTTPS to HTTP after authentication."
    },
    {
      "requirement_id": "KDH-043",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The implementation of automated attack protections like bot detection and WAF settings is best verified by reviewing the configuration and code."
    },
    {
      "requirement_id": "KDH-044",
      "methods": [
        "Test"
      ],
      "rationale": "The one-time use of a TOTP code can be verified by using a valid TOTP code and then attempting to use the same code again."
    },
    {
      "requirement_id": "KDH-045",
      "methods": [
        "Test"
      ],
      "rationale": "The sending of a notification when a new recovery code is issued can be verified by issuing a new code and checking for the notification."
    },
